1	package tracepath
2	
3	import (
4		"encoding/json"
5		"errors"
6		"io"
7		"net/http"
8		"sort"
9		"strconv"
10		"strings"
11	)
12	
13	// Server adapts a Service onto net/http. It owns routing, request decoding and
14	// the documented error shape; every rule lives in the service layer.
15	type Server struct {
16		service *Service
17	}
18	
19	// NewServer builds the HTTP handler for one service.
20	func NewServer(service *Service) *Server {
21		return &Server{service: service}
22	}
23	
24	func (s *Server) ServeHTTP(writer http.ResponseWriter, request *http.Request) {
25		status, response, err := s.dispatch(request, splitPath(request.URL.Path))
26		if err != nil {
27			writeError(writer, err)
28			return
29		}
30		writeJSON(writer, status, response)
31	}
32	
33	func (s *Server) dispatch(request *http.Request, parts []string) (int, any, error) {
34		method := request.Method
35		switch {
36		case method == http.MethodGet && len(parts) == 1 && parts[0] == "health":
37			if err := requireQuery(request); err != nil {
38				return 0, nil, err
39			}
40			return http.StatusOK, map[string]any{"status": "ok"}, nil
41	
42		case method == http.MethodPost && len(parts) == 1 && parts[0] == "spans":
43			body, err := readJSONBody(request)
44			if err != nil {
45				return 0, nil, err
46			}
47			response, err := s.service.IngestSpan(body, request.Header.Get("Idempotency-Key"))
48			return http.StatusCreated, response, err
49	
50		case method == http.MethodGet && len(parts) == 1 && parts[0] == "traces":
51			if err := requireQuery(request, "service", "limit", "q", "operation", "status",
52				"start_from", "start_to", "min_duration_ns", "max_duration_ns", "complete", "valid"); err != nil {
53				return 0, nil, err
54			}
55			filter, err := TraceFilterFromQuery(request.URL.Query())
56			if err != nil {
57				return 0, nil, err
58			}
59			limit := 100
60			if raw := request.URL.Query().Get("limit"); raw != "" {
61				parsed, err := strconv.Atoi(raw)
62				if err != nil {
63					return 0, nil, ValidationError("limit must be an integer")
64				}
65				limit = parsed
66			}
67			response, err := s.service.ListTraces(filter, limit)
68			return http.StatusOK, response, err
69	
70		case method == http.MethodGet && len(parts) == 2 && parts[0] == "traces":
71			if err := requireQuery(request); err != nil {
72				return 0, nil, err
73			}
74			response, err := s.service.GetTrace(parts[1])
75			return http.StatusOK, response, err
76	
77		case method == http.MethodGet && len(parts) == 3 && parts[0] == "traces" && parts[2] == "critical-path":
78			if err := requireQuery(request); err != nil {
79				return 0, nil, err
80			}
81			response, err := s.service.CriticalPath(parts[1])
82			return http.StatusOK, response, err
83	
84		case method == http.MethodGet && len(parts) == 2 && parts[0] == "services" && parts[1] == "graph":
85			if err := requireQuery(request, "trace_id"); err != nil {
86				return 0, nil, err
87			}
88			response, err := s.service.ServiceGraph(strings.TrimSpace(request.URL.Query().Get("trace_id")))
89			return http.StatusOK, response, err
90		}
91		return 0, nil, NotFoundError("route was not found")
92	}
93	
94	func readJSONBody(request *http.Request) ([]byte, error) {
95		contentType := request.Header.Get("Content-Type")
96		mediaType, _, _ := strings.Cut(contentType, ";")
97		if strings.TrimSpace(strings.ToLower(mediaType)) != "application/json" {
98			return nil, ValidationError("Content-Type must be application/json")
99		}
100		body, err := io.ReadAll(io.LimitReader(request.Body, maxBodyBytes+1))
101		if err != nil {
102			return nil, ValidationError("request body could not be read")
103		}
104		if len(body) > maxBodyBytes {
105			return nil, ValidationError("request body must be at most %d bytes", maxBodyBytes)
106		}
107		return body, nil
108	}
109	
110	func splitPath(path string) []string {
111		parts := []string{}
112		for _, part := range strings.Split(path, "/") {
113			if part != "" {
114				parts = append(parts, part)
115			}
116		}
117		return parts
118	}
119	
120	// requireQuery rejects every query parameter that the route does not document.
121	func requireQuery(request *http.Request, allowed ...string) error {
122		names := make([]string, 0, len(request.URL.Query()))
123		for name := range request.URL.Query() {
124			names = append(names, name)
125		}
126		sort.Strings(names)
127		for _, name := range names {
128			known := false
129			for _, candidate := range allowed {
130				if name == candidate {
131					known = true
132					break
133				}
134			}
135			if !known {
136				return ValidationError("unknown query parameter %s", name)
137			}
138		}
139		return nil
140	}
141	
142	// writeError maps a service error onto the documented error body. A trace that
143	// is stored but violates span invariants additionally carries its violations.
144	func writeError(writer http.ResponseWriter, err error) {
145		body := map[string]any{
146			"error": map[string]any{"code": "internal_error", "message": "internal server error"},
147		}
148		status := http.StatusInternalServerError
149		var apiError *Error
150		var invalid *TraceInvalidError
151		switch {
152		case errors.As(err, &invalid):
153			status = http.StatusConflict
154			body = map[string]any{
155				"error": map[string]any{
156					"code":       "trace_invalid",
157					"message":    invalid.Message,
158					"trace_id":   invalid.TraceID,
159					"violations": publicViolations(invalid.Violations),
160				},
161			}
162		case errors.As(err, &apiError):
163			status = apiError.Status
164			body = map[string]any{
165				"error": map[string]any{"code": apiError.Code, "message": apiError.Message},
166			}
167		}
168		writeJSON(writer, status, body)
169	}
170	
171	func writeJSON(writer http.ResponseWriter, status int, value any) {
172		encoded, err := json.Marshal(value)
173		if err != nil {
174			status = http.StatusInternalServerError
175			encoded = []byte(`{"error":{"code":"internal_error","message":"internal server error"}}`)
176		}
177		writer.Header().Set("Content-Type", "application/json; charset=utf-8")
178		writer.Header().Set("Content-Length", strconv.Itoa(len(encoded)))
179		writer.WriteHeader(status)
180		writer.Write(encoded)
181	}
