1	package tracepath
2	
3	import (
4		"net/url"
5		"sort"
6		"strconv"
7		"strings"
8		"time"
9	)
10	
11	// Service implements the TracePath contract on top of a Store. It owns span
12	// ingestion, trace reassembly, critical path analysis, error propagation
13	// marking and the service dependency graph.
14	type Service struct {
15		store *Store
16		clock func() time.Time
17	}
18	
19	// NewService wires a store and an injectable clock.
20	func NewService(store *Store, clock func() time.Time) (*Service, error) {
21		if store == nil {
22			return nil, InternalError("service requires a store")
23		}
24		if clock == nil {
25			clock = time.Now
26		}
27		return &Service{store: store, clock: clock}, nil
28	}
29	
30	func (s *Service) now() string {
31		return s.clock().UTC().Format(idLayout)
32	}
33	
34	// runIdempotent executes action at most once per key. The first response is
35	// re-rendered from committed state for every later request that carries the
36	// same key and the same resource identity, so a replay is byte-identical by
37	// construction. Reusing a key for another operation, or for another resource,
38	// is a conflict.
39	func (s *Service) runIdempotent(key string, operation string, identity string, action func(state *State) (any, error)) (any, error) {
40		if key == "" {
41			return nil, ValidationError("Idempotency-Key header is required")
42		}
43		if len(key) > 200 {
44			return nil, ValidationError("Idempotency-Key must be at most 200 characters")
45		}
46		var response any
47		err := s.store.Update(func(state *State) error {
48			if record, found := state.Idempotency[key]; found {
49				if record.Operation != operation {
50					return ConflictError("idempotency key was already used for another operation")
51				}
52				if record.Identity != identity {
53					return ConflictError("idempotency key was already used for resource %s", record.Identity)
54				}
55				response = identity
56				return nil
57			}
58			value, err := action(state)
59			if err != nil {
60				return err
61			}
62			state.Idempotency[key] = &IdempotencyRecord{
63				Key:       key,
64				Operation: operation,
65				Identity:  identity,
66				CreatedAt: s.now(),
67			}
68			response = value
69			return nil
70		})
71		if err != nil {
72			return nil, err
73		}
74		return response, nil
75	}
76	
77	// spanResponse is the public projection of one ingested span.
78	type spanResponse struct {
79		TraceID    string            `json:"trace_id"`
80		SpanID     string            `json:"span_id"`
81		ParentID   *string           `json:"parent_id"`
82		Service    string            `json:"service"`
83		Operation  string            `json:"operation"`
84		Kind       string            `json:"kind"`
85		StartTime  string            `json:"start_time"`
86		DurationNS int64             `json:"duration_ns"`
87		Status     string            `json:"status"`
88		Attributes map[string]string `json:"attributes"`
89		Accepted   bool              `json:"accepted"`
90		SpanCount  int               `json:"span_count"`
91		Complete   bool              `json:"complete"`
92		Valid      bool              `json:"valid"`
93		Violations []Validation      `json:"violations"`
94	}
95	
96	// renderSpan projects one stored span onto its public projection. The identity
97	// of the projected span is returned as well.
98	func renderSpan(state *State, traceID string, spanID string) (any, error) {
99		spans, found := state.Spans[traceID]
100		if !found {
101			return nil, InternalError("trace %s disappeared during ingestion", traceID)
102		}
103		span, found := spans[spanID]
104		if !found {
105			return nil, InternalError("span %s of trace %s disappeared during ingestion", spanID, traceID)
106		}
107		trace := assembleTrace(traceID, spans)
108		declared := trace.SpanCount
109		if trace.RootSpanCount != 0 {
110			declared = trace.RootSpanCount
111		}
112		response := &spanResponse{
113			TraceID:    span.TraceID,
114			SpanID:     span.SpanID,
115			ParentID:   span.ParentID,
116			Service:    span.Service,
117			Operation:  span.Operation,
118			Kind:       span.Kind,
119			StartTime:  span.StartTime,
120			DurationNS: span.DurationNS,
121			Status:     span.Status,
122			Attributes: map[string]string{},
123			Accepted:   true,
124			SpanCount:  declared,
125			Complete:   trace.Complete,
126			Valid:      trace.Valid,
127			Violations: publicViolations(trace.Violations),
128		}
129		for attribute, value := range span.Attributes {
130			response.Attributes[attribute] = value
131		}
132		return response, nil
133	}
134	
135	// IngestSpan validates and stores one span. Every check that needs the other
136	// spans of the trace (parent existence, trace id agreement, time containment)
137	// runs against the committed state under the store lock.
138	func (s *Service) IngestSpan(body []byte, key string) (any, error) {
139		var input SpanInput
140		if err := decodeObject(body, &input); err != nil {
141			return nil, err
142		}
143		start, err := validateSpanInput(&input)
144		if err != nil {
145			return nil, err
146		}
147		spanID, err := validateIdentifier(input.SpanID, "span_id")
148		if err != nil {
149			return nil, err
150		}
151		traceID, err := validateIdentifier(input.TraceID, "trace_id")
152		if err != nil {
153			return nil, err
154		}
155		operation := "ingest-span"
156		identity := traceID + "/" + spanID
157	
158		if _, err := s.runIdempotent(key, operation, identity, func(state *State) (any, error) {
159			spans, found := state.Spans[traceID]
160			if !found {
161				if parentID := input.ParentID; parentID != nil {
162					if _, elsewhere := findSpan(state, *parentID); elsewhere != nil {
163						return nil, ConflictError("span %s belongs to trace %s but its parent %s belongs to trace %s",
164							spanID, traceID, *parentID, *elsewhere)
165					}
166				}
167				spans = map[string]*SpanInput{}
168				state.Spans[traceID] = spans
169			}
170			if _, duplicate := spans[spanID]; duplicate {
171				return nil, ConflictError("span %s already exists in trace %s", spanID, traceID)
172			}
173			resolved, err := lineOf(spans, &input)
174			if err != nil {
175				return nil, err
176			}
177			if resolved != traceID {
178				return nil, ConflictError("span %s belongs to trace %s but its parent chain resolves to trace %s",
179					spanID, traceID, resolved)
180			}
181			if input.ParentID != nil {
182				parent, found := spans[*input.ParentID]
183				if found {
184					parentStart, _ := parseTime(parent.StartTime, "start_time")
185					parentEnd := parentStart.Add(time.Duration(parent.DurationNS))
186					end := start.Add(time.Duration(input.DurationNS))
187					if start.Before(parentStart) || end.After(parentEnd) {
188						return nil, ConflictError("span %s runs from %s to %s which is not contained in parent %s from %s to %s",
189							spanID, formatTime(start), formatTime(end), parent.SpanID, parent.StartTime, formatTime(parentEnd))
190					}
191				}
192			}
193			clone := input
194			clone.Attributes = map[string]string{}
195			for attribute, value := range input.Attributes {
196				clone.Attributes[attribute] = value
197			}
198			spans[spanID] = &clone
199			return nil, nil
200		}); err != nil {
201			return nil, err
202		}
203		return s.store.View(func(state *State) (any, error) {
204			return renderSpan(state, traceID, spanID)
205		})
206	}
207	
208	// findSpan locates a span id in any trace and returns its trace id.
209	func findSpan(state *State, spanID string) (*SpanInput, *string) {
210		for traceID, spans := range state.Spans {
211			if span, found := spans[spanID]; found {
212				id := traceID
213				return span, &id
214			}
215		}
216		return nil, nil
217	}
218	
219	func publicViolations(violations []Violation) []Validation {
220		public := make([]Validation, 0, len(violations))
221		for _, violation := range violations {
222			public = append(public, Validation{
223				Code:    violation.Code,
224				TraceID: violation.TraceID,
225				SpanID:  violation.SpanID,
226				Message: violation.Message,
227			})
228		}
229		return public
230	}
231	
232	// GetTrace reassembles one trace and fails when it is incomplete or unusable.
233	func (s *Service) GetTrace(traceID string) (any, error) {
234		value, err := s.store.View(func(state *State) (any, error) {
235			spans, found := state.Spans[traceID]
236			if !found {
237				return nil, NotFoundError("trace %s does not exist", traceID)
238			}
239			return assembleTrace(traceID, spans), nil
240		})
241		if err != nil {
242			return nil, err
243		}
244		trace := value.(*Trace)
245		if !trace.Complete {
246			return nil, InvalidTraceError(traceID, append([]Violation{{
247				Code:    "trace_incomplete",
248				TraceID: traceID,
249				SpanID:  "",
250				Message: "trace is not complete yet or its declared span_count does not match the ingested spans",
251			}}, trace.Violations...))
252		}
253		if !trace.Valid {
254			return nil, InvalidTraceError(traceID, trace.Violations)
255		}
256		return trace, nil
257	}
258	
259	// TraceFilter narrows GET /traces. Every condition that is set must hold; a
260	// zero-valued filter keeps every trace. Time and duration fields are present as
261	// pointers so that an unset bound never accidentally matches as zero.
262	type TraceFilter struct {
263		// Query is matched as a Unicode case-insensitive substring of the trace id
264		// or of any span service or operation.
265		Query string
266		// Operation keeps traces that have at least one span with this exact op.
267		Operation string
268		// Service keeps traces that contain this service (the legacy semantics).
269		Service string
270		// Status is "", "error" (at least one error span) or "ok" (no error span).
271		Status string
272		// StartFrom is inclusive and StartTo is exclusive on the root start time.
273		StartFrom *time.Time
274		StartTo   *time.Time
275		// MinDurationNS and MaxDurationNS are both inclusive on the root duration.
276		MinDurationNS *int64
277		MaxDurationNS *int64
278		// Complete and Valid filter on the current reassembly result; nil = unset.
279		Complete *bool
280		Valid    *bool
281	}
282	
283	// TraceFilterFromQuery parses and validates every documented GET /traces
284	// parameter apart from limit, which the HTTP layer keeps. Unknown parameters
285	// are rejected before this is called. All failures are validation errors.
286	func TraceFilterFromQuery(query url.Values) (*TraceFilter, error) {
287		filter := &TraceFilter{
288			Query:   query.Get("q"),
289			Service: strings.TrimSpace(query.Get("service")),
290		}
291		if raw, present := query.Get("operation"), query.Has("operation"); present {
292			operation := strings.TrimSpace(raw)
293			if operation == "" {
294				return nil, ValidationError("operation must not be empty")
295			}
296			filter.Operation = operation
297		}
298		if query.Has("status") {
299			status := query.Get("status")
300			if status != "ok" && status != "error" {
301				return nil, ValidationError("status must be ok or error")
302			}
303			filter.Status = status
304		}
305		if raw, present := query.Get("start_from"), query.Has("start_from"); present {
306			instant, err := parseTime(raw, "start_from")
307			if err != nil {
308				return nil, err
309			}
310			filter.StartFrom = &instant
311		}
312		if raw, present := query.Get("start_to"), query.Has("start_to"); present {
313			instant, err := parseTime(raw, "start_to")
314			if err != nil {
315				return nil, err
316			}
317			filter.StartTo = &instant
318		}
319		if raw, present := query.Get("min_duration_ns"), query.Has("min_duration_ns"); present {
320			value, err := parseDurationBound(raw, "min_duration_ns")
321			if err != nil {
322				return nil, err
323			}
324			filter.MinDurationNS = &value
325		}
326		if raw, present := query.Get("max_duration_ns"), query.Has("max_duration_ns"); present {
327			value, err := parseDurationBound(raw, "max_duration_ns")
328			if err != nil {
329				return nil, err
330			}
331			filter.MaxDurationNS = &value
332		}
333		if filter.MinDurationNS != nil && filter.MaxDurationNS != nil &&
334			*filter.MinDurationNS > *filter.MaxDurationNS {
335			return nil, ValidationError("min_duration_ns must not be greater than max_duration_ns")
336		}
337		if raw, present := query.Get("complete"), query.Has("complete"); present {
338			value, err := parseBoolean(raw, "complete")
339			if err != nil {
340				return nil, err
341			}
342			filter.Complete = &value
343		}
344		if raw, present := query.Get("valid"), query.Has("valid"); present {
345			value, err := parseBoolean(raw, "valid")
346			if err != nil {
347				return nil, err
348			}
349			filter.Valid = &value
350		}
351		return filter, nil
352	}
353	
354	// parseDurationBound accepts a decimal non-negative integer with no sign,
355	// exponent or surrounding space.
356	func parseDurationBound(raw string, field string) (int64, error) {
357		if raw == "" || strings.TrimSpace(raw) == "" {
358			return 0, ValidationError("%s must be a decimal non-negative integer", field)
359		}
360		for _, r := range raw {
361			if r < '0' || r > '9' {
362				return 0, ValidationError("%s must be a decimal non-negative integer", field)
363			}
364		}
365		value, err := strconv.ParseInt(raw, 10, 64)
366		if err != nil {
367			return 0, ValidationError("%s must be a decimal non-negative integer", field)
368		}
369		return value, nil
370	}
371	
372	// parseBoolean accepts exactly "true" or "false".
373	func parseBoolean(raw string, field string) (bool, error) {
374		switch raw {
375		case "true":
376			return true, nil
377		case "false":
378			return false, nil
379		default:
380			return false, ValidationError("%s must be true or false", field)
381		}
382	}
383	
384	// matches reports whether one reassembled trace satisfies every set condition.
385	func (f *TraceFilter) matches(trace *Trace) bool {
386		if f.Service != "" {
387			found := false
388			for _, node := range trace.Spans {
389				if node.Service == f.Service {
390					found = true
391					break
392				}
393			}
394			if !found {
395				return false
396			}
397		}
398		if f.Operation != "" {
399			found := false
400			for _, node := range trace.Spans {
401				if node.Operation == f.Operation {
402					found = true
403					break
404				}
405			}
406			if !found {
407				return false
408			}
409		}
410		if f.Query != "" {
411			if !containsFold(trace.TraceID, f.Query) {
412				found := false
413				for _, node := range trace.Spans {
414					if containsFold(node.Service, f.Query) || containsFold(node.Operation, f.Query) {
415						found = true
416						break
417					}
418				}
419				if !found {
420					return false
421				}
422			}
423		}
424		switch f.Status {
425		case "error":
426			if trace.ErrorSpans == 0 {
427				return false
428			}
429		case "ok":
430			if trace.ErrorSpans != 0 {
431				return false
432			}
433		}
434		if f.Complete != nil && trace.Complete != *f.Complete {
435			return false
436		}
437		if f.Valid != nil && trace.Valid != *f.Valid {
438			return false
439		}
440		if f.StartFrom != nil || f.StartTo != nil || f.MinDurationNS != nil || f.MaxDurationNS != nil {
441			// Every time and duration bound refers to the root. A trace without a
442			// root has neither a root instant nor a root duration, so any such
443			// bound excludes it.
444			if trace.Root == nil {
445				return false
446			}
447		}
448		if f.StartFrom != nil || f.StartTo != nil {
449			rootStart, err := parseTime(trace.Root.StartTime, "start_time")
450			if err != nil {
451				return false
452			}
453			if f.StartFrom != nil && rootStart.Before(*f.StartFrom) {
454				return false
455			}
456			if f.StartTo != nil && !rootStart.Before(*f.StartTo) {
457				return false
458			}
459		}
460		if f.MinDurationNS != nil && trace.DurationNS < *f.MinDurationNS {
461			return false
462		}
463		if f.MaxDurationNS != nil && trace.DurationNS > *f.MaxDurationNS {
464			return false
465		}
466		return true
467	}
468	
469	// ListTraces summarises every stored trace with at least one span.
470	func (s *Service) ListTraces(filter *TraceFilter, limit int) (any, error) {
471		if limit < 1 || limit > 400 {
472			return nil, ValidationError("limit must be between 1 and 400")
473		}
474		if filter == nil {
475			filter = &TraceFilter{}
476		}
477		value, err := s.store.View(func(state *State) (any, error) {
478			summaries := []*TraceSummary{}
479			for _, traceID := range state.traceIDs() {
480				trace := assembleTrace(traceID, state.Spans[traceID])
481				if !filter.matches(trace) {
482					continue
483				}
484				summary := &TraceSummary{
485					TraceID:      trace.TraceID,
486					StartTime:    "",
487					DurationNS:   trace.DurationNS,
488					SpanCount:    trace.SpanCount,
489					ServiceCount: trace.ServiceCount,
490					ErrorSpans:   trace.ErrorSpans,
491					Complete:     trace.Complete,
492					Valid:        trace.Valid,
493				}
494				if trace.Root != nil {
495					rootID := trace.Root.SpanID
496					rootService := trace.Root.Service
497					summary.RootSpanID = &rootID
498					summary.RootService = &rootService
499					summary.StartTime = trace.Root.StartTime
500					summary.rootInstant, _ = parseTime(trace.Root.StartTime, "start_time")
501				}
502				summaries = append(summaries, summary)
503			}
504			sort.Slice(summaries, func(i, j int) bool {
505				if !summaries[i].rootInstant.Equal(summaries[j].rootInstant) {
506					return summaries[i].rootInstant.After(summaries[j].rootInstant)
507				}
508				return summaries[i].TraceID < summaries[j].TraceID
509			})
510			if len(summaries) > limit {
511				summaries = summaries[:limit]
512			}
513			return map[string]any{"traces": summaries}, nil
514		})
515		if err != nil {
516			return nil, err
517		}
518		return value, nil
519	}
520	
521	// CriticalPath walks the root-to-leaf path with the largest total self_time. It
522	// therefore needs time containment to hold, exactly like the invariant
523	// "critical path length equals the root span duration" does.
524	func (s *Service) CriticalPath(traceID string) (any, error) {
525		value, err := s.store.View(func(state *State) (any, error) {
526			spans, found := state.Spans[traceID]
527			if !found {
528				return nil, NotFoundError("trace %s does not exist", traceID)
529			}
530			return assembleTrace(traceID, spans), nil
531		})
532		if err != nil {
533			return nil, err
534		}
535		trace := value.(*Trace)
536		path := &CriticalPath{
537			TraceID:         traceID,
538			Method:          "longest chain below the root, weighted by self_time_ns; ties are broken by the longest sub-chain and then by the smallest span id sequence",
539			TraceDurationNS: trace.DurationNS,
540			Path:            []PathStep{},
541			Complete:        trace.Complete,
542			Valid:           trace.Valid || trace.Root == nil,
543			Violations:      publicViolations(trace.Violations),
544		}
545		if !trace.Complete {
546			path.Valid = false
547		}
548		if trace.Root == nil {
549			return path, nil
550		}
551		_, steps := longestSelfTimePath(trace.Root)
552		path.Path = steps
553		for _, step := range steps {
554			path.LengthNS += step.SelfTimeNS
555		}
556		return path, nil
557	}
558	
559	type pathCandidate struct {
560		// weight is the sum of self_time along the candidate: the value the response
561		// reports as the length of the path.
562		weight int64
563		// path is the longest self_time-weighted path of the subtree, used to break a
564		// tie between two branches that weigh the same.
565		path  int64
566		steps int
567		ids   []string
568	}
569	
570	// better ranks two candidates of the same node. More self_time wins. An equal
571	// weight is settled by the branch with the longer critical path, then by the
572	// shorter path, then by the lexicographically smallest span id sequence, so the
573	// output is deterministic.
574	func better(candidate pathCandidate, incumbent pathCandidate) bool {
575		if candidate.weight != incumbent.weight {
576			return candidate.weight > incumbent.weight
577		}
578		if candidate.path != incumbent.path {
579			return candidate.path > incumbent.path
580		}
581		if candidate.steps != incumbent.steps {
582			return candidate.steps < incumbent.steps
583		}
584		for index := 0; index < len(candidate.ids) && index < len(incumbent.ids); index++ {
585			if candidate.ids[index] != incumbent.ids[index] {
586				return candidate.ids[index] < incumbent.ids[index]
587			}
588		}
589		return len(candidate.ids) < len(incumbent.ids)
590	}
591	
592	// longestSelfTimePath returns the winning candidate of the subtree together
593	// with the steps of the critical path, both in pre-order. The tree builder has
594	// already computed maxPath for every span, so the winner is the child whose
595	// maxPath is the largest and the weight of the result is this node's maxPath.
596	func longestSelfTimePath(node *TraceNode) (pathCandidate, []PathStep) {
597		self := PathStep{
598			SpanID:     node.SpanID,
599			ParentID:   node.ParentID,
600			Service:    node.Service,
601			Operation:  node.Operation,
602			Depth:      node.Depth,
603			SelfTimeNS: node.SelfTimeNS,
604			StartTime:  node.StartTime,
605			EndTime:    node.EndTime,
606		}
607		best := pathCandidate{weight: node.SelfTimeNS, path: node.maxPath, steps: 1, ids: []string{node.SpanID}}
608		var bestSteps []PathStep
609		for _, child := range node.Children {
610			candidate, steps := longestSelfTimePath(child)
611			candidate.weight += node.SelfTimeNS
612			candidate.steps++
613			candidate.ids = append([]string{node.SpanID}, candidate.ids...)
614			if bestSteps == nil || better(candidate, best) {
615				best = candidate
616				bestSteps = steps
617			}
618		}
619		if bestSteps == nil {
620			bestSteps = []PathStep{}
621		}
622		steps := append([]PathStep{self}, bestSteps...)
623		weight := int64(0)
624		for _, item := range steps {
625			weight += item.SelfTimeNS
626		}
627		best.weight = weight
628		if best.weight < node.maxPath {
629			best.weight = node.maxPath
630		}
631		return best, steps
632	}
633	
634	// ServiceGraph aggregates the caller/callee graph. traceID limits the analysis
635	// to one trace; an empty traceID covers every stored trace.
636	func (s *Service) ServiceGraph(traceID string) (any, error) {
637		value, err := s.store.View(func(state *State) (any, error) {
638			graph := &ServiceGraph{
639				Services: []*ServiceStat{},
640				Edges:    []*ServiceEdge{},
641				Stats:    &GraphStats{},
642			}
643			ids := state.traceIDs()
644			if traceID != "" {
645				if _, found := state.Spans[traceID]; !found {
646					return nil, NotFoundError("trace %s does not exist", traceID)
647				}
648				ids = []string{traceID}
649				// The response always echoes an explicitly requested trace.
650				graph.TraceID = &ids[0]
651			}
652			services := map[string]*ServiceStat{}
653			edges := map[string]*ServiceEdge{}
654			graph.Stats.durations = []int64{}
655			for _, id := range ids {
656				trace := assembleTrace(id, state.Spans[id])
657				usable := trace.Valid && trace.Complete && trace.Root != nil
658				if !usable {
659					if traceID != "" {
660						// An explicitly requested trace is reported as-is, complete
661						// or not.
662						graph.Stats.PartialTraces = 1
663						return graph, nil
664					}
665					graph.Stats.PartialTraces++
666					continue
667				}
668				graph.Stats.TraceCount++
669				graph.Stats.SpanCount += trace.SpanCount
670				graph.Stats.ErrorSpans += trace.ErrorSpans
671				graph.Stats.durations = append(graph.Stats.durations, trace.DurationNS)
672				for _, node := range trace.Spans {
673					stat := services[node.Service]
674					if stat == nil {
675						stat = &ServiceStat{Service: node.Service, Operations: []*OperationStat{}, durations: []int64{}}
676						services[node.Service] = stat
677					}
678					stat.SpanCount++
679					stat.SelfTimeNS += node.SelfTimeNS
680					stat.durations = append(stat.durations, node.DurationNS)
681					if node.Error {
682						stat.ErrorSpans++
683					}
684					if node.ParentID == nil {
685						stat.RootSpans++
686					}
687					operation := operationStat(stat, node.Operation)
688					operation.SpanCount++
689					operation.SelfTimeNS += node.SelfTimeNS
690					operation.durations = append(operation.durations, node.DurationNS)
691					if node.Error {
692						operation.ErrorSpans++
693					}
694				}
695				byID := map[string]*TraceNode{}
696				for _, node := range trace.Spans {
697					byID[node.SpanID] = node
698				}
699				for _, node := range trace.Spans {
700					if node.ParentID == nil {
701						continue
702					}
703					parent := byID[*node.ParentID]
704					if parent == nil || parent.Service == node.Service {
705						continue
706					}
707					key := parent.Service + "\x00" + node.Service
708					edge := edges[key]
709					if edge == nil {
710						edge = &ServiceEdge{Caller: parent.Service, Callee: node.Service, durations: []int64{}}
711						edges[key] = edge
712					}
713					edge.CallCount++
714					edge.durations = append(edge.durations, node.DurationNS)
715					if node.Error {
716						edge.ErrorCount++
717					}
718				}
719			}
720			for _, stat := range services {
721				finalizeService(stat)
722				graph.Services = append(graph.Services, stat)
723			}
724			for _, edge := range edges {
725				finalizeEdge(edge)
726				graph.Edges = append(graph.Edges, edge)
727			}
728			sort.Slice(graph.Services, func(i, j int) bool { return graph.Services[i].Service < graph.Services[j].Service })
729			sort.Slice(graph.Edges, func(i, j int) bool {
730				if graph.Edges[i].Caller != graph.Edges[j].Caller {
731					return graph.Edges[i].Caller < graph.Edges[j].Caller
732				}
733				return graph.Edges[i].Callee < graph.Edges[j].Callee
734			})
735			finalizeStats(graph.Stats)
736			return graph, nil
737		})
738		if err != nil {
739			return nil, err
740		}
741		return value, nil
742	}
743	
744	func operationStat(service *ServiceStat, operation string) *OperationStat {
745		for _, stat := range service.Operations {
746			if stat.Operation == operation {
747				return stat
748			}
749		}
750		stat := &OperationStat{Operation: operation, durations: []int64{}}
751		service.Operations = append(service.Operations, stat)
752		return stat
753	}
754	
755	func finalizeService(stat *ServiceStat) {
756		sort.Slice(stat.durations, func(i, j int) bool { return stat.durations[i] < stat.durations[j] })
757		stat.MinDurationNS, stat.MaxDurationNS = bounds(stat.durations)
758		stat.MeanDurationNS = mean(stat.durations)
759		stat.P50DurationNS = percentile(stat.durations, 50)
760		stat.P95DurationNS = percentile(stat.durations, 95)
761		stat.durations = nil
762		sort.Slice(stat.Operations, func(i, j int) bool { return stat.Operations[i].Operation < stat.Operations[j].Operation })
763		for _, operation := range stat.Operations {
764			finalizeOperation(operation)
765		}
766	}
767	
768	func finalizeOperation(stat *OperationStat) {
769		sort.Slice(stat.durations, func(i, j int) bool { return stat.durations[i] < stat.durations[j] })
770		stat.MinDurationNS, stat.MaxDurationNS = bounds(stat.durations)
771		stat.MeanDurationNS = mean(stat.durations)
772		stat.P50DurationNS = percentile(stat.durations, 50)
773		stat.P95DurationNS = percentile(stat.durations, 95)
774		stat.durations = nil
775	}
776	
777	func finalizeEdge(edge *ServiceEdge) {
778		sort.Slice(edge.durations, func(i, j int) bool { return edge.durations[i] < edge.durations[j] })
779		edge.MinDurationNS, edge.MaxDurationNS = bounds(edge.durations)
780		edge.MeanDurationNS = mean(edge.durations)
781		edge.P50DurationNS = percentile(edge.durations, 50)
782		edge.P95DurationNS = percentile(edge.durations, 95)
783		edge.durations = nil
784	}
785	
786	func finalizeStats(stats *GraphStats) {
787		sort.Slice(stats.durations, func(i, j int) bool { return stats.durations[i] < stats.durations[j] })
788		stats.DurationNS, _ = bounds(stats.durations)
789		stats.MeanDurationNS = mean(stats.durations)
790		stats.P50DurationNS = percentile(stats.durations, 50)
791		stats.P95DurationNS = percentile(stats.durations, 95)
792		stats.durations = nil
793	}
794	
795	func bounds(sorted []int64) (int64, int64) {
796		if len(sorted) == 0 {
797			return 0, 0
798		}
799		return sorted[0], sorted[len(sorted)-1]
800	}
801	
802	func mean(sorted []int64) int64 {
803		if len(sorted) == 0 {
804			return 0
805		}
806		total := int64(0)
807		for _, value := range sorted {
808			total += value
809		}
810		return total / int64(len(sorted))
811	}
812	
813	// percentile uses the nearest-rank definition on already sorted input:
814	// index = ceil(p/100 * n) - 1. Input is never mutated.
815	func percentile(sorted []int64, p int) int64 {
816		if len(sorted) == 0 {
817			return 0
818		}
819		rank := (p*len(sorted) + 99) / 100
820		if rank < 1 {
821			rank = 1
822		}
823		if rank > len(sorted) {
824			rank = len(sorted)
825		}
826		return sorted[rank-1]
827	}
828	
829	func sortStrings(values []string) {
830		sort.Strings(values)
831	}
