87		DurationNS int64   `json:"duration_ns"`
88		SelfTimeNS int64   `json:"self_time_ns"`
89		// TotalDurationNS is the duration of the whole subtree of this span, derived
90		// from the declared values rather than from wall-clock arithmetic.
91		TotalDurationNS int64 `json:"subtree_duration_ns"`
92		// maxPath is the longest self_time-weighted path from this span downwards. It
93		// is internal bookkeeping and equals the span duration by construction.
94		maxPath      int64
95		Depth        int               `json:"depth"`
96		Error        bool              `json:"error"`
97		ErrorOrigin  bool              `json:"error_origin"`
98		Propagated   bool              `json:"propagated"`
99		ErrorOrigins []string          `json:"error_origins"`
100		Attributes   map[string]string `json:"attributes"`
101		Children     []*TraceNode      `json:"children"`
102	}
103	
104	// assignTiming derives self_time and the critical path of one subtree.
105	//
106	// LongestPath(t) is the largest sum of self_time on any path from t downwards.
107	// The critical branch K is the child with the largest LongestPath. self_time(t)
108	// is then everything of t's duration that K does not account for:
109	// duration(t) - LongestPath(K), where a leaf is its own critical branch. That
110	// makes self_time exactly the exclusive time off the critical path, so the self
111	// times along the critical path add up to duration(t), which is the invariant
112	// this service promises.
113	//
114	// Children are independent of each other, so LongestPath(child) can be computed
115	// before self_time(t) and does not change afterwards.
116	func assignTiming(node *TraceNode) {
117		if len(node.Children) == 0 {
118			node.SelfTimeNS = node.DurationNS
119			node.maxPath = node.DurationNS
120			return
121		}
122		critical := node.Children[0]
123		for _, child := range node.Children {
124			assignTiming(child)
125			if child.maxPath > critical.maxPath {
126				critical = child
127			}
128		}
129		selfTime := node.DurationNS - critical.maxPath
130		if selfTime < 0 {
131			selfTime = 0
132		}
133		node.SelfTimeNS = selfTime
134		node.maxPath = selfTime + critical.maxPath
135		if node.maxPath > node.DurationNS {
136			node.maxPath = node.DurationNS
137		}
138	}
