	if got := numberOf(t, edges["gateway->db"]["min_duration_ns"]); got != 600 {
		t.Errorf("gateway->db min %d", got)
	}
	if got := numberOf(t, edges["gateway->db"]["max_duration_ns"]); got != 600 {
