		t.Fatalf("services %v", names)
	}
	if got := numberOf(t, services["db"]["span_count"]); got != 3 {
		t.Errorf("db span count %d", got)
	}
	if got := numberOf(t, services["db"]["self_time_ns"]); got != 800 {
		t.Errorf("db self time %d", got)
